     1	use std::fs::{self, File};
     2	use std::io::BufReader;
     3	use std::io::prelude::*;
     4	
     5	use regex::Regex;
     6	
     7	const ACCURACY_BASE:i32 = 90;
     8	
     9	const RESULTSDIR:&str = "./results_2000/";
    10	fn main() -> std::io::Result<()> {
    11	    // Match results regex
    12	    let cargotree_crates_re = Regex::new("cargotree_crates_num = [0-9]+").unwrap();
    13	    let pipeline_crates_re  = Regex::new("pipeline_crates_num = [0-9]+").unwrap();
    14	    let overresolve_re      = Regex::new("overresolve_dep = [0-9]+").unwrap();
    15	    let right_re            = Regex::new("right_dep = [0-9]+").unwrap();
    16	    let wrong_re            = Regex::new("wrong_dep = [0-9]+").unwrap();
    17	    let missing_re          = Regex::new("missing_dep = [0-9]+").unwrap();
    18	    // Results detail table
    19	    let mut accuracy_alarm:Vec<String> = Vec::new();
    20	    let mut pipeline_failure:Vec<String> = Vec::new();
    21	    let mut pipeline_total_overresolve:Vec<String> = Vec::new();
    22	    // Read every results
    23	    let datasets = ["random", "popular", "mostdep"];
    24	    for dataset in datasets {
    25	        println!("Dataset: {}", dataset);
    26	        let paths = fs::read_dir(RESULTSDIR.to_string() + dataset + "/output/results").unwrap();
    27	
    28	        let mut cargotree_crates_num    = 0;
    29	        let mut pipeline_crates_num     = 0;
    30	        let mut overresolve_dep         = 0;
    31	        let mut right_dep               = 0;
    32	        let mut wrong_dep               = 0;
    33	        let mut missing_dep             = 0;
    34	        // Full Accuracy
    35	        let mut crate_count             = 0;
    36	        let mut match_count             = 0;
    37	
    38	        for path_dir in paths {
    39	            let path = path_dir.unwrap().path();
    40	            // Read each file
    41	            // println!("Name: {}", path.display());
    42	            let display = path.display();   
    43	            let file = match File::open(&path) {
    44	                Err(why) => panic!("couldn't create {}: {}", display, why),
    45	                Ok(file) => file,
    46	            };
    47	            let mut buf_reader = BufReader::new(file);
    48	            let mut contents = String::new();
    49	            buf_reader.read_to_string(&mut contents)?;
    50	            // Match data
    51	            let cap_cargotree_crates_num = cargotree_crates_re.captures(&contents).unwrap();
    52	            let cap_pipeline_crates_num  = pipeline_crates_re.captures(&contents).unwrap();
    53	            let cap_overresolve_dep      = overresolve_re.captures(&contents).unwrap();
    54	            let cap_right_dep            = right_re.captures(&contents).unwrap();
    55	            let cap_wrong_dep            = wrong_re.captures(&contents).unwrap();
    56	            let cap_missing_dep          = missing_re.captures(&contents).unwrap();
    57	            let cargotree_crates_num_single = &cap_cargotree_crates_num [0].replace("cargotree_crates_num = ", "").parse::<i32>().unwrap();
    58	            let pipeline_crates_num_single  = &cap_pipeline_crates_num  [0].replace("pipeline_crates_num = ", "").parse::<i32>().unwrap();
    59	            let overresolve_dep_single      = &cap_overresolve_dep      [0].replace("overresolve_dep = ", "").parse::<i32>().unwrap();
    60	            let right_dep_single            = &cap_right_dep            [0].replace("right_dep = ", "").parse::<i32>().unwrap();
    61	            let wrong_dep_single            = &cap_wrong_dep            [0].replace("wrong_dep = ", "").parse::<i32>().unwrap();
    62	            let missing_dep_single          = &cap_missing_dep          [0].replace("missing_dep = ", "").parse::<i32>().unwrap();
    63	    
    64	    
    65	            // Alarm
    66	            if *cargotree_crates_num_single == 0 {
    67	                if *pipeline_crates_num_single != 0 {
    68	                    // Pipiline over-resolve:
    69	                    //      This is caused by local configurations in toml file, and we skip the evaluation of this.
    70	                    //      Now, we can't handle this. But this is the problem from benchmark, not our resolution pipeline.
    71	                    pipeline_total_overresolve.push(display.to_string());
    72	                    continue;
    73	                }
    74	            }
    75	            else if  *pipeline_crates_num_single == 0 {
    76	                pipeline_failure.push(display.to_string());
    77	            }
    78	            else if (right_dep_single * 100) <= (ACCURACY_BASE * cargotree_crates_num_single) {
    79	                accuracy_alarm.push(display.to_string());
    80	            }
    81	    
    82	            
    83	            crate_count += 1;
    84	            if (pipeline_crates_num_single == cargotree_crates_num_single)
    85	                && (pipeline_crates_num_single == right_dep_single){
    86	                match_count += 1;
    87	            }
    88	            
    89	            cargotree_crates_num    += cargotree_crates_num_single;
    90	            pipeline_crates_num     += pipeline_crates_num_single ;
    91	            overresolve_dep         += overresolve_dep_single     ;
    92	            right_dep               += right_dep_single           ;
    93	            wrong_dep               += wrong_dep_single           ;
    94	            missing_dep             += missing_dep_single         ;
    95	        }
    96	    
    97	        let tree_accuracy   = match_count as f64 / crate_count as f64  * 100  as f64;
    98	        let precision       = right_dep as f64 / (right_dep + wrong_dep + overresolve_dep) as f64  * 100  as f64;
    99	        let recall          = right_dep as f64 / (right_dep + missing_dep) as f64  * 100  as f64;
   100	        let f1score         = 2.0 * (recall * precision) / (recall + precision);
   101	    
   102	        // println!("pipeline_total_overresolve : {:#?}", pipeline_total_overresolve);
   103	        // println!("pipeline_failure : {:#?}", pipeline_failure);
   104	        // println!("accuracy_alarm : {:#?}", accuracy_alarm);
   105	    
   106	        println!("crate_count          = {}", crate_count );
   107	        println!("match_count          = {}", match_count );
   108	        println!("cargotree_crates_num = {}", cargotree_crates_num );
   109	        println!("pipeline_crates_num  = {}", pipeline_crates_num  );
   110	        println!("overresolve_dep      = {}", overresolve_dep      );
   111	        println!("right_dep            = {}", right_dep            );
   112	        println!("wrong_dep            = {}", wrong_dep            );
   113	        println!("missing_dep          = {}", missing_dep          );
   114	        println!("Resolution Accuracy Summary: ");
   115	        println!("Tree Accuracy        = {:.3}%", tree_accuracy);
   116	        println!("Precision            = {:.3}%", precision    );
   117	        println!("Recall               = {:.3}%", recall       );
   118	        println!("F1Score              = {:.3}%", f1score      );
   119	        println!("");
   120	    }
   121	    Ok(())
   122	}

