cd /workspace && awk '
/^Dataset:/ { ds=$2 }
/^Tree Accuracy/ { v=$4; gsub("[^0-9.]","",v); tree[ds]=v }
/^Precision/ { v=$3; gsub("[^0-9.]","",v); prec[ds]=v }
/^Recall/ { v=$3; gsub("[^0-9.]","",v); rec[ds]=v }
/^F1Score/ { v=$3; gsub("[^0-9.]","",v); f1[ds]=v }
END {
  print "**Table 1: Resolution accuracy.**";
  print "";
  print "| Dataset Type | Tree Accuracy | Precision | Recall | F1Score |";
  print "| ------------ | ------------: | --------: | -----: | ------: |";
  order[1]="random"; order[2]="popular"; order[3]="mostdep";
  names["random"]="Random"; names["popular"]="Popular"; names["mostdep"]="Mostdep";
  for (i=1;i<=3;i++) {
    ds=order[i];
    t=sprintf("%.2f", tree[ds]);
    p=sprintf("%.2f", prec[ds]);
    r=sprintf("%.2f", rec[ds]);
    f=sprintf("%.2f", f1[ds]);
    printf "| %-12s | %12s%% | %8s%% | %6s%% | %7s%% |\n", names[ds], t, p, r, f;
  }
}
' repro_dev.txt > trial_table.md

